# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BASİT ARAÇ GEREÇLE DİNAMOMETRE MODELİ TASARIMI</text>\n  <rect x="25" y="45" width="310" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kullanılan Malzemeler ve Görevleri</text>\n  <text x="45" y="96" font-size="12" font-weight="bold" fill="#1e3a8a">• Sarmal Yay / Paket Lastiği:</text>\n  <text x="55" y="114" font-size="11" fill="#334155">Kuvvet etkisiyle uzayan esnek iç eleman.</text>\n  <text x="45" y="138" font-size="12" font-weight="bold" fill="#1e3a8a">• Şırınga / Karton Silindir:</text>\n  <text x="55" y="156" font-size="11" fill="#334155">Yayı koruyan dış gövde ve ölçek yüzeyi.</text>\n  <text x="45" y="180" font-size="12" font-weight="bold" fill="#1e3a8a">• Cetvel ve Kalem:</text>\n  <text x="55" y="198" font-size="11" fill="#334155">Eşit bölmeli Newton (N) ölçeği çizimi.</text>\n  <text x="45" y="222" font-size="12" font-weight="bold" fill="#1e3a8a">• Ataç veya Tel Kanca:</text>\n  <text x="200" y="222" font-size="11" fill="#334155">Cisimleri asma ucu.</text>\n\n  <rect x="360" y="45" width="315" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Tasarım ve Kalibrasyon Aşamaları</text>\n  <text x="380" y="98" font-size="12" font-weight="bold" fill="#14532d">1. Sıfır Noktasını Belirleme:</text>\n  <text x="390" y="116" font-size="11" fill="#334155">Kancaya yük asılmamışken uç hizası \'0 N\' işaretlenir.</text>\n  <text x="380" y="144" font-size="12" font-weight="bold" fill="#14532d">2. Eşit Ağırlıklarla Bölmelendirme:</text>\n  <text x="390" y="162" font-size="11" fill="#334155">Özdeş cisimler asıldıkça uzama miktarları eşit</text>\n  <text x="390" y="178" font-size="11" fill="#334155">aralıklarla (1 N, 2 N, 3 N...) ölçeklendirilir.</text>\n  <text x="380" y="204" font-size="12" font-weight="bold" fill="#14532d">3. Test Etme ve Yenileme:</text>\n  <text x="390" y="222" font-size="11" fill="#334155">Farklı ağırlıklarla ölçüm yapılır, model geliştirilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUVVET - UZAMA İLİŞKİSİ VE ESNEKLİK SINIRI</text>\n  <rect x="25" y="48" width="320" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="185" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Doğrusal Uzama Oranı Tablosu</text>\n  <line x1="45" y1="85" x2="325" y2="85" stroke="#ca8a04" stroke-width="1.5"/>\n  <text x="110" y="105" text-anchor="middle" font-size="12" font-weight="bold" fill="#713f12">Uygulanan Kuvvet</text>\n  <text x="255" y="105" text-anchor="middle" font-size="12" font-weight="bold" fill="#713f12">Yaydaki Uzama</text>\n  <text x="110" y="132" text-anchor="middle" font-size="12" fill="#334155">10 N</text>\n  <text x="255" y="132" text-anchor="middle" font-size="12" fill="#334155">2 cm</text>\n  <text x="110" y="158" text-anchor="middle" font-size="12" fill="#334155">20 N</text>\n  <text x="255" y="158" text-anchor="middle" font-size="12" fill="#334155">4 cm</text>\n  <text x="110" y="184" text-anchor="middle" font-size="12" fill="#334155">30 N</text>\n  <text x="255" y="184" text-anchor="middle" font-size="12" fill="#334155">6 cm</text>\n  <text x="185" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Her 5 N kuvvet yayı 1 cm uzatır (Doğru Orantı)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Esneklik Sınırı ve Bozulan Yay</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">50 N kapasiteli dinamometreye</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#e11d48">70 N ağırlık asılırsa ne olur?</text>\n  <text x="520" y="152" text-anchor="middle" font-size="11" fill="#334155">• Yayın esneklik sınırı aşılır.</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#334155">• Yay eski boyuna geri dönemez.</text>\n  <text x="520" y="196" text-anchor="middle" font-size="11" fill="#334155">• Dinamometre kalıcı olarak bozulur ve</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">bir daha doğru ölçüm yapamaz.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİNAMOMETREDE ÖLÇÜM HASSASİYETİNİ ETKİLEYEN FAKTÖRLER</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">İnce Yaylı Hassas Dinamometre</text>\n  <text x="180" y="104" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Örnek: 10 N Kapasiteli (10 Bölmeli)</text>\n  <text x="180" y="130" text-anchor="middle" font-size="11" fill="#334155">• Her 1 bölme = 1 N değerindedir.</text>\n  <text x="180" y="152" text-anchor="middle" font-size="11" fill="#334155">• Küçük kuvvetlerde bile kolayca uzar.</text>\n  <text x="180" y="174" text-anchor="middle" font-size="11" fill="#334155">• Bakır gibi yumuşak ve ince tel kullanılır.</text>\n  <text x="180" y="204" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">Hassasiyeti YÜKSEKTİR (Küçük kuvvetleri ölçer)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Kalın Yaylı Geniş Kapasiteli Dinamometre</text>\n  <text x="520" y="104" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">Örnek: 100 N Kapasiteli (10 Bölmeli)</text>\n  <text x="520" y="130" text-anchor="middle" font-size="11" fill="#334155">• Her 1 bölme = 10 N değerindedir.</text>\n  <text x="520" y="152" text-anchor="middle" font-size="11" fill="#334155">• Küçük kuvvetlerde uzaması fark edilmez.</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#334155">• Çelik gibi sert ve kalın tel kullanılır.</text>\n  <text x="520" y="204" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">Hassasiyeti DÜŞÜKTÜR (Büyük kuvvetleri ölçer)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
